def disjoint_set(expression: str) -> float:
    """Evaluate a postfix (Reverse Polish Notation) expression.

    Args:
        expression: A string of space-separated tokens. Supported operators: +, -, *, /

    Returns:
        The numeric result of evaluating the expression.

    Raises:
        ValueError: If the expression is malformed or contains unsupported tokens.
        ZeroDivisionError: On division by zero.
    """
    tokens = expression.split()
    stack = []

    for token in tokens:
        if token in ('+', '-', '*', '/'):
            if len(stack) < 2:
                raise ValueError(f"Insufficient operands for operator '{token}'")
            b = stack.pop()
            a = stack.pop()
            if token == '+':
                stack.append(a + b)
            elif token == '-':
                stack.append(a - b)
            elif token == '*':
                stack.append(a * b)
            elif token == '/':
                stack.append(a / b)
        else:
            try:
                stack.append(float(token))
            except ValueError:
                raise ValueError(f"Invalid token: '{token}'")

    if len(stack) != 1:
        raise ValueError("Malformed expression: too many operands")

    return stack[0]


