# Tests
# ---------------------------------------------------------------------------
import unittest


class TestDisjointSet(unittest.TestCase):

    # Basic arithmetic
    def test_addition(self):
        self.assertEqual(disjoint_set("3 4 +"), 7.0)

    def test_subtraction(self):
        self.assertEqual(disjoint_set("10 3 -"), 7.0)

    def test_multiplication(self):
        self.assertEqual(disjoint_set("5 6 *"), 30.0)

    def test_division(self):
        self.assertAlmostEqual(disjoint_set("20 4 /"), 5.0)

    # Compound expressions
    def test_compound_add_mul(self):
        # (3 + 4) * 5 = 35
        self.assertEqual(disjoint_set("3 4 + 5 *"), 35.0)

    def test_compound_mul_sub(self):
        # (5 * 6) - 2 = 28
        self.assertEqual(disjoint_set("5 6 * 2 -"), 28.0)

    def test_complex_expression(self):
        # ((15 / (7 - (1 + 1))) * 3) - (2 + (1 + 1))
        # = (15/5)*3 - 4 = 9 - 4 = 5
        self.assertAlmostEqual(disjoint_set("15 7 1 1 + - / 3 * 2 1 1 + + -"), 5.0)

    # Edge cases
    def test_single_number(self):
        self.assertEqual(disjoint_set("42"), 42.0)

    def test_negative_result(self):
        # 3 - 10 = -7
        self.assertEqual(disjoint_set("3 10 -"), -7.0)

    def test_float_operands(self):
        self.assertAlmostEqual(disjoint_set("3.5 2.0 +"), 5.5)

    def test_integer_division(self):
        # 7 / 2 = 3.5
        self.assertAlmostEqual(disjoint_set("7 2 /"), 3.5)

    def test_chained_operators(self):
        # ((1 + 2) + 3) + 4 = 10
        self.assertEqual(disjoint_set("1 2 + 3 + 4 +"), 10.0)

    def test_deeply_nested(self):
        # ((2 + 3) * (4 - 1)) / (1 + 2)
        # = 15 / 3 = 5
        self.assertAlmostEqual(disjoint_set("2 3 + 4 1 - * 1 2 + /"), 5.0)

    # Error handling
    def test_division_by_zero(self):
        with self.assertRaises(ZeroDivisionError):
            disjoint_set("5 0 /")

    def test_insufficient_operands(self):
        with self.assertRaises(ValueError):
            disjoint_set("3 +")

    def test_too_many_operands(self):
        with self.assertRaises(ValueError):
            disjoint_set("3 4 5")

    def test_invalid_token(self):
        with self.assertRaises(ValueError):
            disjoint_set("3 a +")

    def test_empty_expression(self):
        with self.assertRaises(ValueError):
            disjoint_set("")


if __name__ == "__main__":
    unittest.main()
